#!/usr/bin/env node
/**
 * Client API path contract gate (audit F3 prevention).
 *
 * The backend's canonical OpenAPI spec (apps/backend/src/docs/openapi.json) is
 * generated by booting the live Express app, so it is a faithful census of what
 * the server actually serves. Nothing, however, asserted the other direction:
 * that CLIENTS only call paths the server serves. The 2026-08-09 audit found
 * nine admin-portal calls to paths absent from both the spec and Express — they
 * 404 in production, and one was pinned by a jest test asserting the same wrong
 * path. This script closes that direction.
 *
 *   node scripts/ci/check-client-paths.mjs            # gate (exit 1 on findings)
 *   node scripts/ci/check-client-paths.mjs --verbose  # + per-source breakdown
 *   node scripts/ci/check-client-paths.mjs --json     # machine-readable report
 *
 * Load-bearing design notes:
 *
 * - The two client stacks resolve paths differently and must be modelled
 *   separately. Admin passes a path that `toApiV1Endpoint` rewrites and then
 *   prefixes (apps/admin/src/lib/api/core.ts) — `/admin/users` is really served
 *   as `/api/v1/users`. Dart passes a bare SUFFIX, because `ApiConfig.baseUrl`
 *   already ends in `/api/v1` and `VHHttpClient._buildUri` string-concatenates.
 *   ADMIN_REWRITES mirrors the former and is pinned against core.ts by
 *   check-client-paths.test.mjs so the two cannot drift apart silently.
 *
 * - Dart extraction is anchored on the CALL SITE, never on literal shape.
 *   GoRouter route names (`/emr/case-sheet/$admissionId`) are syntactically
 *   indistinguishable from API suffixes, so a shape-based scan would flag
 *   navigation as broken API calls. Anchoring on the client receiver
 *   (`ApiClient.get`, `VHHttpClient.post`, the per-service `_get` forwarders,
 *   and `${ApiConfig.baseUrl}`-interpolated raw http) removes the ambiguity.
 *
 * - Non-API strings are excluded BY RULE, never by allowlist: Next.js local
 *   routes live under `/api/<not v1>`, the websocket path is `/ws`, Swagger UI
 *   is `/api-docs`, static assets are `/_next|/static|/assets`, and policy
 *   globs contain `*`. See RULE_EXCLUDED_PATTERNS.
 *
 * - Declaration-only router mount bases (a path that is not itself an
 *   operation but is the segment-boundary prefix of real operations) pass by
 *   rule. A known-method call to the same path fails: a mount is not an
 *   operation. Rewrite-backed aliases are mapped to their canonical spec paths
 *   and checked there; the allowlist is exact-path and method-scoped.
 *
 * - Matching is two-tier. Strict: a `{param}` in the client path may only match
 *   a `{...}` in the spec. Lenient: it may also match a literal segment. A path
 *   that matches strictly PASSES; one that matches only leniently is AMBIGUOUS
 *   and reported without failing (an interpolated segment can legitimately
 *   carry a literal); one that matches under neither reading cannot resolve to
 *   any served endpoint under the most generous binding, and FAILS.
 *
 * - Unresolvable call sites (a non-literal argument, or a literal whose prefix
 *   is itself an unresolved interpolation) are counted and reported, never
 *   failed on. They are a coverage statistic, not a defect.
 */

import { readdirSync, readFileSync, existsSync } from 'node:fs';
import { dirname, join, relative, resolve, sep } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import process from 'node:process';

export const repoRoot = resolve(dirname(fileURLToPath(import.meta.url)), '..', '..');

export const SPEC_PATH = 'apps/backend/src/docs/openapi.json';
export const ALLOWLIST_PATH = 'scripts/ci/client-path-allowlist.json';

/** Placeholder every path parameter normalizes to, on both sides of the compare. */
export const PARAM = '{param}';

/**
 * Admin helpers that run their first argument through `toApiV1Endpoint`
 * (rewrite table + `/api/v1` prefix), mapped to the HTTP method they send.
 * `null` means the method is carried in the call's options object and has to be
 * read from there. apps/admin/src/lib/api/core.ts.
 */
export const ADMIN_REWRITING_FUNCTIONS = new Map([
  ['fetchAdminAPI', null],
  ['requestJSON', null],
  ['getJSON', 'GET'],
  ['getJSONEnvelope', 'GET'],
  ['postJSON', 'POST'],
  ['postJSONEnvelope', 'POST'],
  ['putJSON', 'PUT'],
  ['deleteJSON', 'DELETE'],
]);

/**
 * Admin helpers that send the path verbatim — callers pass a full `/api/v1`
 * path. apps/admin/src/lib/api-fetch.ts, apps/admin/src/lib/api-client.ts.
 */
export const ADMIN_VERBATIM_FUNCTIONS = new Map([
  ['apiFetch', null],
  ['apiGet', 'GET'],
  ['authenticatedFetch', null],
]);

/**
 * Dart request receivers, mapped to the method they send.
 * `multipartFileFromPath` is deliberately absent: it takes a FILESYSTEM path
 * (9 staff call sites) and would be 9 false positives.
 */
export const DART_CLIENT_METHODS = new Map([
  ['get', 'GET'],
  ['getBytes', 'GET'],
  ['cachedGet', 'GET'],
  ['post', 'POST'],
  ['put', 'PUT'],
  ['patch', 'PATCH'],
  ['delete', 'DELETE'],
  ['multipart', 'POST'],
]);
export const DART_CLIENT_RECEIVERS = ['ApiClient', 'VHHttpClient'];
/** Per-service private forwarders that take `String path` and forward it. */
export const DART_FORWARDERS = new Map([
  ['_get', 'GET'],
  ['_defaultGet', 'GET'],
  ['_post', 'POST'],
  ['_put', 'PUT'],
  ['_patch', 'PATCH'],
  ['_delete', 'DELETE'],
]);

/** Verb a request defaults to when the options object names none. */
export const DEFAULT_METHOD = 'GET';

/**
 * Strings that look path-shaped but are not backend REST operations. Excluded
 * by rule so the allowlist stays reserved for real server-side aliases.
 */
export const RULE_EXCLUDED_PATTERNS = [
  // Next.js route handlers under apps/admin/src/app/api/* — login, logout,
  // refresh, act-as, realtime-ticket, sso. Same-origin, never proxied verbatim.
  /^\/api\/(?!v1(?:\/|$))/,
  // Swagger UI + raw spec surface, not an operation.
  /^\/api-docs(?:\/|$)/,
  // WebSocket upgrade path (NEXT_PUBLIC_WS_URL), not REST.
  /^\/ws(?:\/|$)/,
  // Static assets and Next internals.
  /^\/_next(?:\/|$)/,
  /^\/static(?:\/|$)/,
  /^\/assets(?:\/|$)/,
  /^\/images(?:\/|$)/,
  /\.(?:js|css|png|jpe?g|gif|svg|ico|woff2?|ttf|eot)$/,
  // Admin portal page routes (Next App Router), not API calls.
  /^\/dashboard(?:\/|$)/,
  /^\/login(?:\/|$)/,
  /^\/logout(?:\/|$)/,
];

/** Policy globs (api-config PROTECTED_ROUTES) are patterns, not call sites. */
export const GLOB_MARKER = '*';

/**
 * Source trees to scan. `kind` selects the extractor and the path-resolution
 * rule. Dart test/integration_test trees are outside `lib/` and so are excluded
 * by scoping rather than by a filter.
 */
export const SOURCES = [
  {
    id: 'admin',
    kind: 'admin',
    root: 'apps/admin/src',
    extensions: ['.ts', '.tsx'],
    excludeDirs: ['__tests__', '__mocks__', 'node_modules'],
    excludeFiles: [/\.test\.tsx?$/, /\.spec\.tsx?$/, /\.d\.ts$/, /openapi\.generated\.ts$/],
  },
  {
    id: 'patient',
    kind: 'dart',
    root: 'apps/patient/lib',
    extensions: ['.dart'],
    excludeDirs: ['generated', 'l10n'],
    excludeFiles: [/\.g\.dart$/, /\.freezed\.dart$/, /\.swagger\.dart$/],
  },
  {
    id: 'staff',
    kind: 'dart',
    root: 'apps/staff/lib',
    extensions: ['.dart'],
    excludeDirs: ['generated', 'l10n'],
    excludeFiles: [/\.g\.dart$/, /\.freezed\.dart$/, /\.swagger\.dart$/],
  },
  {
    id: 'core',
    kind: 'dart',
    root: 'packages/vhhealth_core/lib',
    extensions: ['.dart'],
    // lib/api/generated is uncommitted build_runner output that mirrors the
    // spec by construction; it could only ever restate it.
    excludeDirs: ['generated', 'l10n'],
    excludeFiles: [/\.g\.dart$/, /\.freezed\.dart$/, /\.swagger\.dart$/],
  },
  {
    id: 'device-gateway',
    kind: 'node',
    root: 'apps/device-gateway/src',
    extensions: ['.js', '.mjs'],
    excludeDirs: ['node_modules'],
    excludeFiles: [/\.test\.m?js$/],
  },
];

/* ────────────────────────────────────────────────────────────────────────────
 * Admin runtime rewrite mirror
 *
 * Mirrors normalizeAdminEndpoint + toApiV1Endpoint from
 * apps/admin/src/lib/api/core.ts. Pinned by check-client-paths.test.mjs.
 * ──────────────────────────────────────────────────────────────────────────── */

/**
 * Exact-match rewrites the admin client applies before prepending /api/v1.
 * Keys are the pre-rewrite path with any /api/v1 prefix already stripped.
 */
export const ADMIN_REWRITES = new Map([
  ['/admin/users', '/users'],
  ['/admin/doctors', '/doctors'],
  ['/admin/departments', '/departments'],
  ['/feedback', '/feedback/recent'],
  ['/feedback/stats', '/feedback/dashboard'],
  ['/notifications', '/notifications/admin/manage'],
  ['/notifications/stats', '/notifications/admin/overview'],
  ['/admin/appointments', '/appointments/list'],
  ['/appointments', '/appointments/list'],
]);

/** Mirror of `toApiV1Endpoint(path)`; input may or may not carry /api/v1. */
export function applyAdminRewrites(path) {
  // normalizeAdminEndpoint selects aliases from the path portion before it
  // restores the query string. Do the same here; otherwise a real call such
  // as `/admin/users?${params}` misses the exact rewrite and is checked against
  // the wrong `/api/v1/admin/users` surface.
  const operationPath = segmentsOf(path).join('/');
  const stripped = operationPath.startsWith('/api/v1')
    ? operationPath.slice(7) || '/'
    : operationPath;
  const rewritten = ADMIN_REWRITES.get(stripped) ?? stripped;
  return rewritten.startsWith('/api/v1') ? rewritten : `/api/v1${rewritten}`;
}

/* ────────────────────────────────────────────────────────────────────────────
 * Lexing
 * ──────────────────────────────────────────────────────────────────────────── */

/**
 * Blank out comments while preserving byte offsets so line numbers stay exact.
 * String-aware, so a `https://` inside a literal is not read as a comment.
 */
export function stripComments(source, lang) {
  const out = source.split('');
  const n = source.length;
  let i = 0;
  const blank = (from, to) => {
    for (let k = from; k < to && k < n; k += 1) {
      if (out[k] !== '\n' && out[k] !== '\r') out[k] = ' ';
    }
  };

  while (i < n) {
    const ch = source[i];
    const next = source[i + 1];

    if (ch === '/' && next === '/') {
      let end = source.indexOf('\n', i);
      if (end === -1) end = n;
      blank(i, end);
      i = end;
      continue;
    }
    if (ch === '/' && next === '*') {
      let end = source.indexOf('*/', i + 2);
      end = end === -1 ? n : end + 2;
      blank(i, end);
      i = end;
      continue;
    }
    if (ch === '"' || ch === "'" || ch === '`') {
      const triple = source.slice(i, i + 3);
      if (lang === 'dart' && (triple === "'''" || triple === '"""')) {
        const close = source.indexOf(triple, i + 3);
        i = close === -1 ? n : close + 3;
        continue;
      }
      const literal = readStringLiteral(source, i, lang);
      i = literal ? literal.end : i + 1;
      continue;
    }
    i += 1;
  }

  return out.join('');
}

/**
 * Read one string literal starting at `start` (which must be the quote, or the
 * `r` of a Dart raw string). Handles `${...}` interpolation with nesting, so a
 * nested template literal inside an interpolation does not terminate the outer
 * one — `` `/prescriptions/all${qs ? `?${qs}` : ""}` `` reads as one literal.
 * Returns null when the literal is unterminated.
 */
export function readStringLiteral(source, start, lang) {
  const n = source.length;
  const isRaw = lang === 'dart' && source[start] === 'r' && /['"]/.test(source[start + 1] || '');
  const quoteIndex = isRaw ? start + 1 : start;
  const quote = source[quoteIndex];
  if (quote !== '"' && quote !== "'" && quote !== '`') return null;

  let i = quoteIndex + 1;
  let value = '';

  while (i < n) {
    const ch = source[i];
    if (ch === '\\' && !isRaw) {
      value += source[i + 1] ?? '';
      i += 2;
      continue;
    }
    if (ch === quote) {
      return { value, start, end: i + 1, raw: isRaw, quote };
    }
    if (ch === '\n' && quote !== '`') return null; // unterminated single-line
    if (!isRaw && ch === '$' && source[i + 1] === '{') {
      const close = readInterpolation(source, i + 1, lang);
      value += source.slice(i, close);
      i = close;
      continue;
    }
    value += ch;
    i += 1;
  }
  return null;
}

/** Given the offset of `{` opening an interpolation, return the offset past `}`. */
export function readInterpolation(source, braceIndex, lang) {
  const n = source.length;
  let depth = 0;
  let i = braceIndex;
  while (i < n) {
    const ch = source[i];
    if (ch === '{') {
      depth += 1;
      i += 1;
      continue;
    }
    if (ch === '}') {
      depth -= 1;
      i += 1;
      if (depth === 0) return i;
      continue;
    }
    if (ch === '"' || ch === "'" || ch === '`') {
      const nested = readStringLiteral(source, i, lang);
      i = nested ? nested.end : i + 1;
      continue;
    }
    i += 1;
  }
  return n;
}

/**
 * Collect string literals with their offsets. Adjacent literals separated only
 * by whitespace are merged — both Dart and TS concatenate them implicitly, and
 * the repo has one such path split mid-segment.
 */
export function scanStringLiterals(source, lang) {
  const literals = [];
  const n = source.length;
  let i = 0;

  while (i < n) {
    const ch = source[i];
    const isQuote = ch === '"' || ch === "'" || ch === '`';
    const isRawStart = lang === 'dart' && ch === 'r' && /['"]/.test(source[i + 1] || '');
    if (isQuote || isRawStart) {
      const literal = readStringLiteral(source, i, lang);
      if (literal) {
        literals.push(literal);
        i = literal.end;
        continue;
      }
    }
    i += 1;
  }

  const merged = [];
  for (const lit of literals) {
    const prev = merged[merged.length - 1];
    if (prev && source.slice(prev.end, lit.start).trim() === '') {
      prev.value += lit.value;
      prev.end = lit.end;
      continue;
    }
    merged.push({ ...lit });
  }
  return merged;
}

/** Map a byte offset to a 1-indexed line number. */
export function lineAt(source, offset) {
  let line = 1;
  for (let i = 0; i < offset && i < source.length; i += 1) {
    if (source[i] === '\n') line += 1;
  }
  return line;
}

/* ────────────────────────────────────────────────────────────────────────────
 * Normalization
 * ──────────────────────────────────────────────────────────────────────────── */

/** `/api/v1/users/{id}/roles` -> `/api/v1/users/{param}/roles` */
export function normalizeSpecPath(p) {
  return p.replace(/\{[^}]*\}/g, PARAM);
}

/**
 * Walk a literal at interpolation depth 0, splitting on `/` and cutting at the
 * first `?` or `#`. Interpolation bodies are opaque — a `?` inside `${a ? b :
 * c}` is an operator, not a query separator, and `${data?.unit.id}` must not
 * truncate the path.
 */
export function segmentsOf(literal) {
  const segments = [];
  let current = '';
  let i = 0;
  while (i < literal.length) {
    const ch = literal[i];
    if (ch === '$' && literal[i + 1] === '{') {
      const close = readInterpolation(literal, i + 1, 'ts');
      current += literal.slice(i, close);
      i = close;
      continue;
    }
    if (ch === '?' || ch === '#') break;
    if (ch === '/') {
      segments.push(current);
      current = '';
      i += 1;
      continue;
    }
    current += ch;
    i += 1;
  }
  segments.push(current);
  return segments;
}

const INTERPOLATION_RE = /\$\{|\$[A-Za-z_]/;
const COLON_PARAM_RE = /^:[A-Za-z_][A-Za-z0-9_]*$/;
/** Spec-style placeholder, as written in api-config leaves and ApiData<> keys. */
const BRACE_PARAM_RE = /^\{[^}]+\}$/;

/**
 * True when `segment` is a literal prefix followed by exactly one interpolation
 * that runs to the end — `all${qs ? '?'+qs : ''}` or `case-sheet$id`.
 */
function trailingInterpolationPrefix(segment) {
  const at = segment.search(INTERPOLATION_RE);
  if (at <= 0) return null;
  // A prefix ending in a connector (`prefix-${id}`, `v${n}_x`) is concatenated
  // INTO the value, so the literal reading is meaningless. Only a prefix that
  // ends a word (`all${qs…}`) can stand alone as the real segment.
  if (!/[A-Za-z0-9]$/.test(segment.slice(0, at))) return null;
  const rest = segment.slice(at);
  const consumed =
    rest[1] === '{'
      ? readInterpolation(rest, 1, 'ts')
      : (/^\$[A-Za-z_][A-Za-z0-9_]*(?:\.[A-Za-z_][A-Za-z0-9_]*)*/.exec(rest) || [''])[0].length;
  return consumed === rest.length ? segment.slice(0, at) : null;
}

/** Cap on generated candidates, so a path full of interpolations cannot blow up. */
const MAX_CANDIDATES = 8;

/**
 * Normalize a raw client literal into the set of paths it could resolve to,
 * most specific first.
 *
 * A segment containing an interpolation normally collapses wholly to {param},
 * because OpenAPI models parameters at segment granularity — `prefix-${id}` and
 * `${id}` are the same shape to the router. But a segment whose interpolation
 * TRAILS a literal is ambiguous in a way that matters: in
 * `/prescriptions/all${qs ? `?${qs}` : ""}` the interpolation contributes a
 * query string, not a path segment, so the real path is `/prescriptions/all`.
 * Collapsing that to {param} let it match an unrelated `/prescriptions/{id}`
 * and pass for the wrong reason. Such segments therefore yield two candidates —
 * the literal prefix, then {param} — and the most specific match wins.
 *
 * A `:name` segment (API_ENDPOINTS leaves consumed via `.replace(":name", v)`)
 * and a `{name}` segment (spec-style placeholders in ApiData<> type keys) are
 * exactly resolvable declared parameters, so they map to {param} but are NOT
 * counted as interpolated: they must match strictly, never leniently.
 *
 * `unresolvedPrefix` marks a literal whose leading segment is an unresolved
 * interpolation, making the real path unknowable statically.
 */
export function normalizeClientPath(literal) {
  const segments = segmentsOf(literal);
  let interpolated = false;

  const perSegment = segments.map((segment, index) => {
    if (index === 0) return [segment]; // the empty string before the leading '/'
    if (COLON_PARAM_RE.test(segment) || BRACE_PARAM_RE.test(segment)) return [PARAM];
    if (!INTERPOLATION_RE.test(segment)) return [segment];
    interpolated = true;
    const prefix = trailingInterpolationPrefix(segment);
    return prefix ? [prefix, PARAM] : [PARAM];
  });

  let combos = [[]];
  for (const options of perSegment) {
    const next = [];
    for (const combo of combos) {
      for (const option of options) {
        if (next.length < MAX_CANDIDATES) next.push([...combo, option]);
      }
    }
    combos = next;
  }

  const tidy = (parts) => {
    const joined = parts.join('/');
    return joined.length > 1 && joined.endsWith('/') ? joined.slice(0, -1) : joined;
  };
  const candidates = [...new Set(combos.map(tidy))];
  const unresolvedPrefix = perSegment.length > 1 && perSegment[1].every((o) => o === PARAM);

  return { path: candidates[0], candidates, interpolated, unresolvedPrefix };
}

/** True when a literal could be a backend REST path worth checking. */
export function isCheckablePathLiteral(value) {
  if (!value.startsWith('/')) return false;
  if (value.includes(' ')) return false;
  if (value.includes(GLOB_MARKER)) return false; // PROTECTED_ROUTES policy globs
  if (value.startsWith('//')) return false; // protocol-relative URL
  return true;
}

/** True when a literal is excluded by rule (not by allowlist). */
export function isRuleExcluded(value) {
  const [path] = value.split('?');
  return RULE_EXCLUDED_PATTERNS.some((re) => re.test(path));
}

/**
 * The admin browser leg prefixes `/api/proxy`, which the Next route handler
 * strips 1:1 before forwarding. Two call sites hard-code it.
 */
export function stripProxyPrefix(value) {
  return value.startsWith('/api/proxy/') ? value.slice('/api/proxy'.length) : value;
}

/* ────────────────────────────────────────────────────────────────────────────
 * Extraction
 * ──────────────────────────────────────────────────────────────────────────── */

function calleeRegex(names, { receivers } = {}) {
  const alternation = [...names.keys()].join('|');
  const callee = receivers
    ? String.raw`(?:${receivers.join('|')})\s*\.\s*(${alternation})`
    : String.raw`(${alternation})`;
  // An optional generic argument list may not contain parens, which stops the
  // match from running past the call's own open paren.
  return new RegExp(String.raw`(?<![.\w$])${callee}\s*(?:<[^()<>]*>)?\s*\(`, 'g');
}

/** Read `method: "POST"` out of a call's own argument region. */
export function methodFromCallOptions(region) {
  const m = /\bmethod\s*:\s*['"`]([A-Za-z]+)['"`]/.exec(region);
  return m ? m[1].toUpperCase() : null;
}

/**
 * Find the first argument of every call to `regex`. Returns the string literal
 * at that position plus the HTTP method — implied by the callee name where the
 * helper is verb-specific (`postJSON`), otherwise read from the options object
 * that follows the path argument (`fetchAdminAPI(p, { method: "POST" })`).
 */
function firstArgumentLiterals(code, regex, literalByStart, methods, lang) {
  const hits = [];
  const misses = [];
  let m;
  while ((m = regex.exec(code)) !== null) {
    const openParen = m.index + m[0].length - 1;
    const callEnd = readCallArguments(code, openParen, lang);
    let k = openParen + 1;
    while (k < code.length && /\s/.test(code[k])) k += 1;
    const via = m[0].replace(/\s*\($/, '').replace(/\s+/g, '');
    const declared = methods.get(m[1]);
    const literal = literalByStart.get(k);
    // Scan for `method:` only AFTER the path argument, so a `method` key inside
    // the path itself can never be read as the verb.
    const region = code.slice(literal ? literal.end : k, callEnd);
    const method = declared ?? methodFromCallOptions(region) ?? DEFAULT_METHOD;
    if (literal) hits.push({ literal, via, method });
    else misses.push({ offset: k, text: code.slice(k, callEnd), via, method });
  }
  return { hits, misses, dynamic: misses.length };
}

/**
 * Top-level tables in api-config.ts that hold path PATTERNS rather than call
 * sites: route-policy globs and a legacy alias map. Their literals are skipped
 * by rule — matching them against operations is a category error.
 */
export const ADMIN_POLICY_TABLES = ['PROTECTED_ROUTES', 'ENDPOINT_MAPPING', 'WS_ENDPOINTS'];

/** Byte ranges of the named top-level const initializers, for exclusion. */
export function policyTableRanges(code, names = ADMIN_POLICY_TABLES) {
  const ranges = [];
  for (const name of names) {
    const re = new RegExp(String.raw`\bconst\s+${name}\b[^=]*=\s*`, 'g');
    let m;
    while ((m = re.exec(code)) !== null) {
      const start = m.index + m[0].length;
      const open = code[start];
      const close = open === '[' ? ']' : open === '{' ? '}' : null;
      if (!close) continue;
      let depth = 0;
      let i = start;
      while (i < code.length) {
        const ch = code[i];
        if (ch === open) depth += 1;
        else if (ch === close) {
          depth -= 1;
          if (depth === 0) {
            i += 1;
            break;
          }
        } else if (ch === '"' || ch === "'" || ch === '`') {
          const lit = readStringLiteral(code, i, 'ts');
          i = lit ? lit.end : i + 1;
          continue;
        }
        i += 1;
      }
      ranges.push([start, i]);
    }
  }
  return ranges;
}

const inAnyRange = (offset, ranges) => ranges.some(([a, b]) => offset >= a && offset < b);

/**
 * Parse `API_ENDPOINTS` from api-config.ts into dotted key -> path.
 *
 * Leaves are either a string ("/api/v1/users/:identifier") or an arrow function
 * returning a template (`(id) => `/api/v1/appointments/${id}/confirm``). Both
 * reduce to the first string literal after the key, which is exactly what the
 * call site sends once the argument is substituted.
 */
export function parseEndpointMap(source) {
  const code = stripComments(source, 'ts');
  const map = new Map();
  const decl = /\bconst\s+API_ENDPOINTS\b[^=]*=\s*\{/.exec(code);
  if (!decl) return map;

  const start = decl.index + decl[0].length - 1;
  const end = readBalanced(code, start, '{', '}');
  const stack = [];
  const keyRe = /([A-Za-z_$][\w$]*|"[^"]+"|'[^']+')\s*:/g;
  keyRe.lastIndex = start + 1;

  let depth = 1;
  let i = start + 1;
  while (i < end) {
    const ch = code[i];
    if (ch === '}') {
      depth -= 1;
      stack.length = Math.max(0, depth - 1);
      i += 1;
      continue;
    }
    if (ch === '"' || ch === "'" || ch === '`') {
      const lit = readStringLiteral(code, i, 'ts');
      i = lit ? lit.end : i + 1;
      continue;
    }
    keyRe.lastIndex = i;
    const m = keyRe.exec(code);
    if (!m || m.index !== i) {
      if (ch === '{') depth += 1;
      i += 1;
      continue;
    }

    const key = m[1].replace(/^['"]|['"]$/g, '');
    let j = m.index + m[0].length;
    while (j < end && /\s/.test(code[j])) j += 1;

    if (code[j] === '{') {
      stack[depth - 1] = key;
      depth += 1;
      i = j + 1;
      continue;
    }

    // Leaf: the first string literal before this entry's own comma/brace.
    let k = j;
    let literal = null;
    while (k < end) {
      const c = code[k];
      if (c === '"' || c === "'" || c === '`') {
        literal = readStringLiteral(code, k, 'ts');
        break;
      }
      if (c === ',' || c === '}') break;
      k += 1;
    }
    if (literal) {
      map.set([...stack.slice(0, depth - 1), key].join('.'), literal.value);
      i = literal.end;
    } else {
      i = j + 1;
    }
  }
  return map;
}

/** Offset just past the bracket matching the one at `start`. */
export function readBalanced(source, start, open, close) {
  let depth = 0;
  let i = start;
  while (i < source.length) {
    const ch = source[i];
    if (ch === open) depth += 1;
    else if (ch === close) {
      depth -= 1;
      i += 1;
      if (depth === 0) return i;
      continue;
    } else if (ch === '"' || ch === "'" || ch === '`') {
      const lit = readStringLiteral(source, i, 'ts');
      i = lit ? lit.end : i + 1;
      continue;
    }
    i += 1;
  }
  return source.length;
}

/**
 * Anchored at the start of the argument, so an API_ENDPOINTS reference in a
 * LATER argument can never be mistaken for the path.
 */
const ENDPOINT_REF_RE = /^API_ENDPOINTS\.([A-Za-z_$][\w$.]*)/;

/**
 * Resolve a dotted reference to a leaf, tolerating a trailing method chain —
 * `users.byRole.replace` resolves via the `users.byRole` leaf, whose `:role`
 * placeholder the normalizer already understands.
 */
export function resolveEndpointRef(dotted, endpointMap) {
  const parts = dotted.split('.').filter(Boolean);
  for (let i = parts.length; i > 0; i -= 1) {
    const key = parts.slice(0, i).join('.');
    if (endpointMap.has(key)) return { key, path: endpointMap.get(key) };
  }
  return null;
}

/** Substitute `${API_ENDPOINTS.a.b}` inside a template literal. */
export function substituteEndpointRefs(value, endpointMap) {
  return value.replace(/\$\{\s*API_ENDPOINTS\.([A-Za-z_$][\w$.]*?)\s*\}/g, (match, key) =>
    endpointMap.has(key) ? endpointMap.get(key) : match,
  );
}

function resolveAdminFetchLiteral(value, endpointMap) {
  return substituteEndpointRefs(value, endpointMap).replace(
    /^\$\{\s*API_BASE_URL\s*\}/,
    '',
  );
}

/**
 * Admin extraction. Four complementary passes:
 *  1. First argument of a rewriting helper (catches bare `/admin/users`).
 *  2. First argument of a verbatim helper (full `/api/v1` paths).
 *  3. First argument that is an `API_ENDPOINTS.a.b` reference — resolved through
 *     the parsed map. Without this the gate is blind to exactly the class the
 *     audit found: a correct path leaf invoked with a verb it does not serve.
 *  4. Any remaining literal anchored at `/api/v1/`.
 */
export function extractAdminPaths(source, { endpointMap = new Map() } = {}) {
  const code = stripComments(source, 'ts');
  const literals = scanStringLiterals(code, 'ts');
  const literalByStart = new Map(literals.map((l) => [l.start, l]));
  const skipRanges = policyTableRanges(code);
  const found = [];
  const seen = new Set();

  const rewriting = firstArgumentLiterals(
    code,
    calleeRegex(ADMIN_REWRITING_FUNCTIONS),
    literalByStart,
    ADMIN_REWRITING_FUNCTIONS,
    'ts',
  );
  const verbatim = firstArgumentLiterals(
    code,
    calleeRegex(ADMIN_VERBATIM_FUNCTIONS),
    literalByStart,
    ADMIN_VERBATIM_FUNCTIONS,
    'ts',
  );

  let unresolved = 0;
  for (const [pass, rewrite] of [
    [rewriting, true],
    [verbatim, false],
  ]) {
    for (const { literal, via, method } of pass.hits) {
      if (seen.has(literal.start)) continue;
      seen.add(literal.start);
      found.push({
        value: substituteEndpointRefs(literal.value, endpointMap),
        offset: literal.start,
        via,
        method,
        rewrite,
      });
    }
    // An argument that is not a literal may still be an API_ENDPOINTS
    // reference, which resolves exactly.
    for (const miss of pass.misses) {
      const ref = ENDPOINT_REF_RE.exec(miss.text);
      const resolved = ref && resolveEndpointRef(ref[1], endpointMap);
      if (resolved) {
        found.push({
          value: resolved.path,
          offset: miss.offset,
          via: `${miss.via}(API_ENDPOINTS.${resolved.key})`,
          method: miss.method,
          rewrite,
        });
      } else {
        unresolved += 1;
      }
    }
  }

  // Direct browser/server fetch calls that concatenate API_BASE_URL are not
  // routed through the helpers above. Bind their first argument to the same
  // API_ENDPOINTS map and keep the call's real/default verb; checking only the
  // exported endpoint literal would miss wrong-method production 404s.
  const fetchFunctions = new Map([['fetch', null]]);
  for (const pass of [
    firstArgumentLiterals(
      code,
      calleeRegex(fetchFunctions),
      literalByStart,
      fetchFunctions,
      'ts',
    ),
    firstArgumentLiterals(
      code,
      calleeRegex(fetchFunctions, { receivers: ['window'] }),
      literalByStart,
      fetchFunctions,
      'ts',
    ),
  ]) {
    for (const { literal, via, method } of pass.hits) {
      if (seen.has(literal.start)) continue;
      seen.add(literal.start);
      found.push({
        value: resolveAdminFetchLiteral(literal.value, endpointMap),
        offset: literal.start,
        via,
        method,
        rewrite: false,
      });
    }
    for (const miss of pass.misses) {
      const ref = ENDPOINT_REF_RE.exec(miss.text);
      const resolved = ref && resolveEndpointRef(ref[1], endpointMap);
      if (resolved) {
        found.push({
          value: resolved.path,
          offset: miss.offset,
          via: `${miss.via}(API_ENDPOINTS.${resolved.key})`,
          method: miss.method,
          rewrite: false,
        });
      } else {
        unresolved += 1;
      }
    }
  }

  // Config-table pass (audit R11, 2026-08-10): bare-suffix literals stored
  // under an `endpoint:` property and invoked later through a variable
  // (`fetchAdminAPI(config.endpoint)`) evaded every pass above — the call site
  // is non-literal and the anchored sweep only catches `/api/v1/…` strings.
  // The report-builder's `/attendance/admin/records` 404'd in production this
  // way. An `endpoint:` property in admin code is by convention a
  // rewriting-helper path, so treat it exactly like a fetchAdminAPI literal.
  // The verb is unknowable here, so these check path existence only.
  const endpointProp = /\bendpoint\s*:\s*/g;
  let ep;
  while ((ep = endpointProp.exec(code)) !== null) {
    const literal = literalByStart.get(ep.index + ep[0].length);
    if (!literal || seen.has(literal.start)) continue;
    if (inAnyRange(literal.start, skipRanges)) continue;
    seen.add(literal.start);
    found.push({
      value: substituteEndpointRefs(literal.value, endpointMap),
      offset: literal.start,
      via: 'endpoint-property',
      method: null,
      rewrite: true,
    });
  }

  // Anchored sweep: exported path consts, ApiData<> spec keys, and helpers this
  // list does not know about. The verb is not knowable here, so these are
  // checked for path existence only. Policy tables are skipped by rule.
  for (const literal of literals) {
    if (seen.has(literal.start)) continue;
    if (inAnyRange(literal.start, skipRanges)) continue;
    if (!stripProxyPrefix(literal.value).startsWith('/api/v1/')) continue;
    found.push({
      value: literal.value,
      offset: literal.start,
      via: 'literal',
      method: null,
      rewrite: false,
    });
    seen.add(literal.start);
  }

  return { found, dynamicCallSites: unresolved };
}

/** Resolve file-local `static const _x = '/literal';` so `'$_x/rest'` resolves. */
export function collectDartPathConstants(code) {
  const constants = new Map();
  const re = /\b(?:static\s+)?const\s+(?:String\s+)?(_?[A-Za-z][A-Za-z0-9_]*)\s*=\s*'(\/[^']*)'/g;
  let m;
  while ((m = re.exec(code)) !== null) {
    if (!m[2].includes('$')) constants.set(m[1], m[2]);
  }
  return constants;
}

/** Substitute `$name` / `${name}` for a known file-local path constant. */
export function substituteDartConstants(value, constants) {
  return value.replace(/\$\{?(_?[A-Za-z][A-Za-z0-9_]*)\}?/g, (match, name) =>
    constants.has(name) ? constants.get(name) : match,
  );
}

/** The raw-http shape: `'${ApiConfig.baseUrl}/suffix'`. */
const API_CONFIG_BASE_RE = /^\$\{\s*ApiConfig\.baseUrl\s*\}/;

function inferDartHttpMethod(code, literal) {
  const before = code.slice(Math.max(0, literal.start - 240), literal.start);
  const direct = /\b(?:http|[A-Za-z_$][\w$]*[Cc]lient)\s*\.\s*(get|post|put|patch|delete|head)\s*\(\s*(?:Uri\.parse\s*\(\s*)?$/i.exec(
    before,
  );
  if (direct) return direct[1].toUpperCase();

  const assignment = /\b(?:final|const|var)\s+(?:Uri\s+)?([A-Za-z_$][\w$]*)\s*=\s*Uri\.parse\s*\(\s*$/.exec(
    before,
  );
  if (!assignment) return null;

  const escaped = assignment[1].replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const call = new RegExp(
    `\\b(?:http|[A-Za-z_$][\\w$]*[Cc]lient)\\s*\\.\\s*` +
      `(get|post|put|patch|delete|head)\\s*\\(\\s*${escaped}\\b`,
    'gi',
  );
  const methods = new Set();
  const after = code.slice(literal.end);
  let match;
  while ((match = call.exec(after)) !== null) methods.add(match[1].toUpperCase());
  return methods.size === 1 ? [...methods][0] : null;
}

/**
 * Dart extraction, anchored on the call site.
 *
 * GoRouter route literals are syntactically identical to API suffixes, so the
 * anchor must be the receiver, not the string. Covered: `ApiClient.<m>()` /
 * `VHHttpClient.<m>()`, the per-service private `_get`/`_post` forwarders that
 * take `String path`, `sendPreparedMutation(path: …)` (a NAMED argument), and
 * raw `package:http` calls that interpolate `${ApiConfig.baseUrl}`.
 */
export function extractDartPaths(source) {
  const code = stripComments(source, 'dart');
  const literals = scanStringLiterals(code, 'dart');
  const literalByStart = new Map(literals.map((l) => [l.start, l]));
  const constants = collectDartPathConstants(code);
  const found = [];
  const seen = new Set();
  let dynamicCallSites = 0;

  const push = (literal, via, method) => {
    if (seen.has(literal.start) || literal.raw) return;
    seen.add(literal.start);
    found.push({
      value: substituteDartConstants(literal.value, constants),
      offset: literal.start,
      via,
      method,
      rewrite: false,
    });
  };

  const client = firstArgumentLiterals(
    code,
    calleeRegex(DART_CLIENT_METHODS, { receivers: DART_CLIENT_RECEIVERS }),
    literalByStart,
    DART_CLIENT_METHODS,
    'dart',
  );
  for (const { literal, via, method } of client.hits) push(literal, via, method);
  dynamicCallSites += client.dynamic;

  const forwarders = firstArgumentLiterals(
    code,
    calleeRegex(DART_FORWARDERS),
    literalByStart,
    DART_FORWARDERS,
    'dart',
  );
  for (const { literal, via, method } of forwarders.hits) push(literal, via, method);
  dynamicCallSites += forwarders.dynamic;

  // sendPreparedMutation takes `path:` as a named argument. Scan only inside
  // that call's own parens so the generic `path:` name (which GoRoute also
  // uses) can never be picked up from anywhere else.
  const prepared = /(?<![\w$])(?:[A-Za-z_$][\w$]*\s*\.\s*)?sendPreparedMutation\s*\(/g;
  let m;
  while ((m = prepared.exec(code)) !== null) {
    const end = readCallArguments(code, m.index + m[0].length - 1, 'dart');
    const region = code.slice(m.index, end);
    const named = /\bpath\s*:\s*/g;
    let nm;
    while ((nm = named.exec(region)) !== null) {
      const literal = literalByStart.get(m.index + nm.index + nm[0].length);
      if (literal) {
        push(literal, 'sendPreparedMutation(path:)', methodFromCallOptions(region));
      } else {
        dynamicCallSites += 1;
      }
    }
  }

  // Raw package:http call sites that interpolate the API base directly.
  for (const literal of literals) {
    if (seen.has(literal.start) || literal.raw) continue;
    if (!API_CONFIG_BASE_RE.test(literal.value)) continue;
    seen.add(literal.start);
    found.push({
      value: substituteDartConstants(literal.value.replace(API_CONFIG_BASE_RE, ''), constants),
      offset: literal.start,
      via: 'ApiConfig.baseUrl',
      method: inferDartHttpMethod(code, literal),
      rewrite: false,
    });
  }

  return { found, dynamicCallSites };
}

/**
 * Return the offset just past the `)` that closes the enclosing call. Accepts
 * either the offset of the opening `(` or any offset already inside the
 * argument list — in the latter case the first unbalanced `)` ends the region.
 */
export function readCallArguments(source, openParen, lang = 'ts') {
  const n = source.length;
  let depth = 0;
  let i = openParen;
  while (i < n) {
    const ch = source[i];
    if (ch === '(') depth += 1;
    else if (ch === ')') {
      depth -= 1;
      i += 1;
      if (depth <= 0) return i;
      continue;
    } else if (ch === '"' || ch === "'" || ch === '`') {
      const literal = readStringLiteral(source, i, lang);
      i = literal ? literal.end : i + 1;
      continue;
    }
    i += 1;
  }
  return n;
}

/**
 * Device gateway extraction. Every backend URL is
 * `` `${this.baseUrl}<literal>` `` — the origin is dynamic, the path is not.
 * The verb sits in the fetch options object that follows the URL.
 */
export function extractNodePaths(source) {
  const code = stripComments(source, 'ts');
  const found = [];
  for (const literal of scanStringLiterals(code, 'ts')) {
    const value = literal.value.replace(/^\$\{[^}]*\}/, '');
    if (!value.startsWith('/api/v1/')) continue;
    // The options object is the next argument; bound the scan at the end of the
    // enclosing call so a later call's method cannot bleed in.
    const region = code.slice(literal.end, readCallArguments(code, literal.end, 'ts'));
    found.push({
      value,
      offset: literal.start,
      via: 'literal',
      method: methodFromCallOptions(region) ?? DEFAULT_METHOD,
      rewrite: false,
    });
  }
  return { found, dynamicCallSites: 0 };
}

export const EXTRACTORS = {
  admin: extractAdminPaths,
  dart: extractDartPaths,
  node: extractNodePaths,
};

/**
 * Resolve a raw literal to the path the runtime will actually request.
 * Admin: `toApiV1Endpoint` (rewrites + prefix) for rewriting helpers, bare
 * prefix otherwise. Dart/node: `ApiConfig.baseUrl` already ends in `/api/v1`,
 * so a bare suffix is prefixed and an already-prefixed path is left alone.
 */
export function resolveRuntimePath(value, kind, rewrite) {
  const path = stripProxyPrefix(value);
  if (kind === 'admin' && rewrite) return applyAdminRewrites(path);
  return path.startsWith('/api/v1') ? path : `/api/v1${path}`;
}

/** Map rewrite-backed runtime aliases onto the canonical OpenAPI operation. */
export function canonicalizeRuntimeAlias(path, method) {
  const operationPath = segmentsOf(path).join('/');
  for (const prefix of ['/api/v1/emr/mar', '/api/v1/nursing/mar']) {
    if (operationPath === prefix || operationPath.startsWith(`${prefix}/`)) {
      return `/api/v1/clinical/mar${operationPath.slice(prefix.length)}`;
    }
  }

  const admissions = '/api/v1/admissions';
  if (operationPath === admissions) {
    if (method === 'GET') return `${admissions}/admissions`;
    if (method === 'POST') return `${admissions}/admit`;
    return operationPath;
  }
  if (operationPath === `${admissions}/stats`) return `${admissions}/admissions/stats`;
  if (operationPath === `${admissions}/advise`) return `${admissions}/admissions/advise`;
  if (operationPath.startsWith(`${admissions}/patient/`)) {
    return `${admissions}/admissions${operationPath.slice(admissions.length)}`;
  }

  const admissionId = operationPath.slice(admissions.length + 1);
  if (
    operationPath.startsWith(`${admissions}/`) &&
    !admissionId.includes('/') &&
    /^(?:\d+|:[^/]+|\{[^/]+\}|\$[A-Za-z_$][\w$.]*|\$\{.+\})$/.test(admissionId)
  ) {
    return `${admissions}/admission/${admissionId}`;
  }
  return operationPath;
}

/* ────────────────────────────────────────────────────────────────────────────
 * Matching
 * ──────────────────────────────────────────────────────────────────────────── */

/** OpenAPI keys that are operations rather than path-level metadata. */
const HTTP_METHODS = ['get', 'put', 'post', 'delete', 'options', 'head', 'patch', 'trace'];

/**
 * Index the spec by normalized path -> set of served methods. Accepts either
 * `{ '/p': { get: {...} } }` (the real spec) or `{ '/p': ['GET'] }` (tests).
 */
export function buildSpecIndex(specPaths) {
  const entries = Array.isArray(specPaths)
    ? specPaths.map((p) => [p, null])
    : Object.entries(specPaths);

  const exact = new Map();
  const bySegmentCount = new Map();
  for (const [raw, item] of entries) {
    const normalized = normalizeSpecPath(raw);
    const methods = Array.isArray(item)
      ? item.map((v) => v.toUpperCase())
      : item && typeof item === 'object'
        ? Object.keys(item)
            .filter((k) => HTTP_METHODS.includes(k.toLowerCase()))
            .map((k) => k.toUpperCase())
        : [];
    if (!exact.has(normalized)) {
      exact.set(normalized, new Set());
      const segments = normalized.split('/');
      if (!bySegmentCount.has(segments.length)) bySegmentCount.set(segments.length, []);
      bySegmentCount.get(segments.length).push(segments);
    }
    for (const method of methods) exact.get(normalized).add(method);
  }

  const prefixes = new Set();
  for (const normalized of exact.keys()) {
    const segments = normalized.split('/');
    for (let i = 2; i < segments.length; i += 1) {
      prefixes.add(segments.slice(0, i).join('/'));
    }
  }
  return { exact, bySegmentCount, prefixes, all: [...exact.keys()] };
}

/** Closest spec path that actually serves `method` — the "did you mean". */
export function closestSpecPathForMethod(path, index, method) {
  const candidates = method
    ? index.all.filter((p) => {
        const methods = index.exact.get(p);
        return methods.size === 0 || methods.has(method);
      })
    : index.all;
  return closestSpecPath(path, { ...index, all: candidates });
}

/**
 * Lenient match: a client {param} may stand in for a literal spec segment.
 * Used only to downgrade a would-be failure to "ambiguous".
 */
export function matchesLeniently(path, index) {
  const segments = path.split('/');
  const candidates = index.bySegmentCount.get(segments.length) || [];
  return candidates.some((candidate) =>
    candidate.every(
      (specSegment, i) =>
        segments[i] === specSegment || segments[i] === PARAM || specSegment === PARAM,
    ),
  );
}

/** Segment-boundary prefix of a real operation — a router mount base. */
export function isMountBase(path, index) {
  return !index.exact.has(path) && index.prefixes.has(path);
}

export function matchesAllowlist(path, allowlist, method = null) {
  if (!method) return null;
  for (const entry of allowlist) {
    if (entry.path !== path) continue;
    if (!entry.methods.includes(method)) continue;
    return entry;
  }
  return null;
}

/** Levenshtein distance, iterative two-row. */
export function editDistance(a, b) {
  if (a === b) return 0;
  if (a.length === 0) return b.length;
  if (b.length === 0) return a.length;
  let prev = Array.from({ length: b.length + 1 }, (_, i) => i);
  for (let i = 1; i <= a.length; i += 1) {
    const row = [i];
    for (let j = 1; j <= b.length; j += 1) {
      const cost = a[i - 1] === b[j - 1] ? 0 : 1;
      row[j] = Math.min(row[j - 1] + 1, prev[j] + 1, prev[j - 1] + cost);
    }
    prev = row;
  }
  return prev[b.length];
}

/** Closest real spec path, for the "did you mean" line on a failure. */
export function closestSpecPath(path, index) {
  let best = null;
  let bestScore = Infinity;
  const segments = path.split('/').length;
  for (const candidate of index.all) {
    if (Math.abs(candidate.length - path.length) > bestScore) continue;
    let score = editDistance(path, candidate);
    if (candidate.split('/').length !== segments) score += 1;
    if (score < bestScore) {
      bestScore = score;
      best = candidate;
    }
  }
  return best === null ? null : { path: best, distance: bestScore };
}

/* ────────────────────────────────────────────────────────────────────────────
 * Walking
 * ──────────────────────────────────────────────────────────────────────────── */

export function walkFiles(root, { extensions, excludeDirs = [], excludeFiles = [] }) {
  const out = [];
  const stack = [root];
  while (stack.length > 0) {
    const dir = stack.pop();
    let entries;
    try {
      entries = readdirSync(dir, { withFileTypes: true });
    } catch {
      continue;
    }
    for (const entry of entries) {
      const full = join(dir, entry.name);
      if (entry.isDirectory()) {
        if (excludeDirs.includes(entry.name)) continue;
        stack.push(full);
        continue;
      }
      if (!extensions.some((ext) => entry.name.endsWith(ext))) continue;
      if (excludeFiles.some((re) => re.test(entry.name))) continue;
      out.push(full);
    }
  }
  return out.sort();
}

/* ────────────────────────────────────────────────────────────────────────────
 * Orchestration
 * ──────────────────────────────────────────────────────────────────────────── */

export function loadAllowlist(root = repoRoot) {
  const file = join(root, ALLOWLIST_PATH);
  if (!existsSync(file)) return [];
  const entries = JSON.parse(readFileSync(file, 'utf8')).entries || [];
  for (const entry of entries) {
    if (
      !entry.path ||
      entry.path.includes('*') ||
      !entry.comment ||
      !Array.isArray(entry.methods) ||
      entry.methods.length === 0 ||
      entry.methods.some((method) => !HTTP_METHODS.includes(String(method).toLowerCase()))
    ) {
      throw new Error(
        `${ALLOWLIST_PATH}: every entry needs an exact "path", a non-empty "methods" array, ` +
          `and a "comment" — got ${JSON.stringify(entry)}`,
      );
    }
  }
  return entries;
}

export function loadSpecIndex(root = repoRoot) {
  const spec = JSON.parse(readFileSync(join(root, SPEC_PATH), 'utf8'));
  return buildSpecIndex(spec.paths || {});
}

export const ADMIN_CONFIG_PATH = 'apps/admin/src/lib/api-config.ts';

export function loadEndpointMap(root = repoRoot) {
  const file = join(root, ADMIN_CONFIG_PATH);
  return existsSync(file) ? parseEndpointMap(readFileSync(file, 'utf8')) : new Map();
}

export function analyze({ root = repoRoot, sources = SOURCES, index, allowlist } = {}) {
  const specIndex = index || loadSpecIndex(root);
  const allow = allowlist || loadAllowlist(root);
  const endpointMap = loadEndpointMap(root);

  const findings = [];
  const ambiguous = [];
  const stats = {
    filesScanned: 0,
    checked: 0,
    inSpec: 0,
    mountBases: 0,
    allowlisted: 0,
    ruleExcluded: 0,
    dynamicCallSites: 0,
    unresolvableLiterals: 0,
  };
  const perSource = [];

  for (const source of sources) {
    const rootDir = join(root, source.root);
    if (!existsSync(rootDir)) continue;
    const extract = EXTRACTORS[source.kind];
    const files = walkFiles(rootDir, source);
    const sourceStats = { id: source.id, files: files.length, checked: 0, findings: 0, dynamic: 0 };

    for (const file of files) {
      const text = readFileSync(file, 'utf8');
      const { found, dynamicCallSites } = extract(text, { endpointMap });
      stats.filesScanned += 1;
      stats.dynamicCallSites += dynamicCallSites;
      sourceStats.dynamic += dynamicCallSites;

      for (const hit of found) {
        const bare = stripProxyPrefix(hit.value);
        if (!isCheckablePathLiteral(bare) || isRuleExcluded(bare)) {
          stats.ruleExcluded += 1;
          continue;
        }
        const runtimePath = canonicalizeRuntimeAlias(
          resolveRuntimePath(hit.value, source.kind, hit.rewrite),
          hit.method,
        );
        const { path, candidates, interpolated, unresolvedPrefix } =
          normalizeClientPath(runtimePath);

        // An endpoint-property literal is a config-table value whose consumer
        // either passes it to a rewriting helper as-is (report-builder) or
        // prepends `/admin` first (clinical-ai TierGenericPanel). Both
        // consumptions are legitimate, so the literal fails only when NEITHER
        // reading resolves to a served operation.
        let effectiveCandidates = candidates;
        if (hit.via === 'endpoint-property') {
          const adminVariant = normalizeClientPath(
            resolveRuntimePath(
              `/admin${stripProxyPrefix(hit.value)}`,
              source.kind,
              hit.rewrite,
            ),
          );
          effectiveCandidates = [...candidates, ...adminVariant.candidates];
        }

        if (unresolvedPrefix) {
          stats.unresolvableLiterals += 1;
          sourceStats.dynamic += 1;
          continue;
        }

        stats.checked += 1;
        sourceStats.checked += 1;

        // Built lazily: line lookup is a scan from the start of the file, and
        // only findings and ambiguities ever need it.
        const record = (resolved) => ({
          source: source.id,
          file: relative(root, file).split(sep).join('/'),
          line: lineAt(text, hit.offset),
          called: hit.value,
          resolved,
          method: hit.method,
          via: hit.via,
        });

        // Candidates are ordered most-specific first. A path passes as soon as
        // ANY reading of it resolves to a served operation; it only fails when
        // no reading does.
        let methodMiss = null;
        let outcome = null;
        for (const candidate of effectiveCandidates) {
          if (matchesAllowlist(candidate, allow, hit.method)) {
            outcome = 'allowlisted';
            break;
          }
          const servedMethods = specIndex.exact.get(candidate);
          if (servedMethods) {
            // The verb is unknown for anchored literals with no call site; a
            // path with no declared operations cannot contradict anything.
            if (!hit.method || servedMethods.size === 0 || servedMethods.has(hit.method)) {
              outcome = 'inSpec';
              break;
            }
            // Express 404s a request whose method has no handler exactly as it
            // 404s an unknown path — a path-only gate waves this through.
            methodMiss ??= { candidate, servedMethods };
            continue;
          }
          // A declaration-only literal may name a router mount. An extracted
          // call with a known verb is an operation, though: accepting its URL
          // merely because longer routes share the prefix would hide the same
          // production 404 this gate exists to prevent.
          if (!hit.method && isMountBase(candidate, specIndex)) {
            outcome = 'mountBases';
            break;
          }
        }

        if (outcome) {
          stats[outcome] += 1;
          continue;
        }
        if (methodMiss) {
          findings.push({
            ...record(methodMiss.candidate),
            reason: 'method',
            servedMethods: [...methodMiss.servedMethods].sort(),
          });
          sourceStats.findings += 1;
          continue;
        }
        if (interpolated && effectiveCandidates.some((c) => matchesLeniently(c, specIndex))) {
          ambiguous.push(record(path));
          continue;
        }
        findings.push({ ...record(path), reason: 'path' });
        sourceStats.findings += 1;
      }
    }
    perSource.push(sourceStats);
  }

  // Suggestions run only over real findings, not the whole corpus.
  for (const finding of findings) {
    const suggestion = closestSpecPathForMethod(finding.resolved, specIndex, finding.method);
    finding.suggestion = suggestion ? suggestion.path : null;
    finding.suggestionDistance = suggestion ? suggestion.distance : null;
  }

  findings.sort((a, b) =>
    a.file === b.file ? a.line - b.line : a.file.localeCompare(b.file, 'en'),
  );

  return { findings, ambiguous, stats, perSource };
}

function formatReport(result, { verbose }) {
  const lines = [];
  const { stats, findings, ambiguous } = result;

  lines.push('Client API path contract gate');
  lines.push(
    `  scanned ${stats.filesScanned} files, ${stats.checked} checkable path(s): ` +
      `${stats.inSpec} in spec, ${stats.mountBases} mount base(s), ${stats.allowlisted} allowlisted`,
  );
  lines.push(
    `  report-only: ${stats.dynamicCallSites} non-literal call site(s), ` +
      `${stats.unresolvableLiterals} unresolvable literal(s), ` +
      `${ambiguous.length} ambiguous interpolation(s)`,
  );

  if (verbose) {
    lines.push('');
    for (const s of result.perSource) {
      lines.push(
        `  ${s.id.padEnd(16)} files=${String(s.files).padStart(5)} ` +
          `checked=${String(s.checked).padStart(5)} findings=${String(s.findings).padStart(3)} ` +
          `dynamic=${String(s.dynamic).padStart(4)}`,
      );
    }
    if (ambiguous.length > 0) {
      lines.push('');
      lines.push('Ambiguous (an interpolated segment could carry a literal — not failed):');
      for (const a of ambiguous) lines.push(`  ${a.file}:${a.line}  ${a.called}`);
    }
  }

  if (findings.length === 0) {
    lines.push('');
    lines.push('OK — every extracted client path resolves to a served endpoint.');
    return lines.join('\n');
  }

  const missingPath = findings.filter((f) => f.reason === 'path');
  const wrongMethod = findings.filter((f) => f.reason === 'method');

  lines.push('');
  lines.push(
    `${findings.length} client call(s) do not resolve to a served operation in ${SPEC_PATH} ` +
      `(${missingPath.length} unknown path, ${wrongMethod.length} unserved method). ` +
      'These 404 at runtime.',
  );
  lines.push('');
  for (const f of findings) {
    lines.push(`  ${f.file}:${f.line}`);
    lines.push(
      `    calls    ${f.method ?? '???'} ${f.called}` +
        `${f.via === 'literal' ? '' : `   (via ${f.via})`}`,
    );
    if (f.resolved !== f.called) lines.push(`    resolves ${f.resolved}`);
    if (f.reason === 'method') {
      lines.push(`    served   ${f.resolved} exists, but only for [${f.servedMethods.join(', ')}]`);
    }
    lines.push(
      f.suggestion
        ? `    closest  ${f.method ?? ''} ${f.suggestion}`.trimEnd() +
            `   (edit distance ${f.suggestionDistance})`
        : '    closest  (no similar path in spec)',
    );
    lines.push('');
  }
  lines.push('Fix the call site. Only if the backend genuinely serves this path as a');
  lines.push(`runtime alias absent from the spec, add it to ${ALLOWLIST_PATH}`);
  lines.push('with a comment naming the app.js mount that serves it.');

  return lines.join('\n');
}

function main(argv) {
  const result = analyze();
  if (argv.includes('--json')) console.log(JSON.stringify(result, null, 2));
  else console.log(formatReport(result, { verbose: argv.includes('--verbose') }));
  return result.findings.length === 0 ? 0 : 1;
}

const invokedDirectly =
  process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href;

if (invokedDirectly) {
  process.exit(main(process.argv.slice(2)));
}
